import{_ as a,o as i,c as e,a5 as t}from"./chunks/framework.BrSBneze.js";const k=JSON.parse('{"title":"Isaac Lab integration","description":"","frontmatter":{},"headers":[],"relativePath":"simulation/isaac-lab.md","filePath":"simulation/isaac-lab.md","lastUpdated":1788882780000}'),n={name:"simulation/isaac-lab.md"};function l(p,s,r,h,d,o){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="isaac-lab-integration" tabindex="-1">Isaac Lab integration <a class="header-anchor" href="#isaac-lab-integration" aria-label="Permalink to &quot;Isaac Lab integration&quot;">​</a></h1><p>The <a href="https://github.com/EESC-LabRoM/isaaclab-hiveboard" target="_blank" rel="noreferrer"><code>EESC-LabRoM/isaaclab-hiveboard</code></a> repository provides Isaac Lab environments for running HiveBoard tasks with Spot, Franka, and ANYmal platforms.</p><p>The instructions below correspond to the repository&#39;s <code>master</code> branch at commit <a href="https://github.com/EESC-LabRoM/isaaclab-hiveboard/commit/769d034d9b5bfd71e34310a5f6fd2b5c1628c6d9" target="_blank" rel="noreferrer"><code>769d034</code></a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>The versions are pinned in the repository&#39;s <a href="https://github.com/EESC-LabRoM/isaaclab-hiveboard/blob/master/pyproject.toml" target="_blank" rel="noreferrer"><code>pyproject.toml</code></a>:</p><table tabindex="0"><thead><tr><th>Component</th><th>Version</th></tr></thead><tbody><tr><td>Python</td><td>3.11</td></tr><tr><td>Isaac Sim</td><td>5.1.0</td></tr><tr><td>Isaac Lab</td><td>2.3.2.post1</td></tr><tr><td>Package manager</td><td><code>uv</code></td></tr></tbody></table><p>The project also installs CuRobo and uses Git submodules for the HiveBoard assets, CuRobo, and the DynaArm description.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Clone the repository with all submodules:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recurse-submodules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/EESC-LabRoM/isaaclab-hiveboard.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> isaaclab-hiveboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>For an existing clone created without <code>--recurse-submodules</code>, initialize the dependencies before running an environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>Run commands through <code>uv run</code> so that the pinned project environment is used.</p><h2 id="verify-the-installation" tabindex="-1">Verify the installation <a class="header-anchor" href="#verify-the-installation" aria-label="Permalink to &quot;Verify the installation&quot;">​</a></h2><p>List all registered HiveBoard environments:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/list_envs.py</span></span></code></pre></div><p>The list can be filtered by robot or mechanism:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/list_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --keyword</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Franka</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/list_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --keyword</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BallValve</span></span></code></pre></div><h2 id="benchmark-environments" tabindex="-1">Benchmark environments <a class="header-anchor" href="#benchmark-environments" aria-label="Permalink to &quot;Benchmark environments&quot;">​</a></h2><p>The following primary task IDs are registered in <a href="https://github.com/EESC-LabRoM/isaaclab-hiveboard/blob/master/source/isaaclab_hiveboard/isaaclab_hiveboard/tasks/__init__.py" target="_blank" rel="noreferrer"><code>tasks/__init__.py</code></a>:</p><table tabindex="0"><thead><tr><th>Task ID</th><th>Platform</th><th>Mechanism</th></tr></thead><tbody><tr><td><code>Isaac-HiveBoard-Spot-BallValve-v0</code></td><td>Spot with arm</td><td>Ball valve</td></tr><tr><td><code>Isaac-HiveBoard-Spot-CircuitBreaker-v0</code></td><td>Spot with arm</td><td>Circuit breaker</td></tr><tr><td><code>Isaac-HiveBoard-Spot-HighTorqueValve-v0</code></td><td>Spot with arm</td><td>High-torque gate valve</td></tr><tr><td><code>Isaac-HiveBoard-Spot-SmallValve-v0</code></td><td>Spot with arm</td><td>Small gate valve</td></tr><tr><td><code>Isaac-HiveBoard-Spot-Lamp-v0</code></td><td>Spot with arm</td><td>Threaded lamp</td></tr><tr><td><code>Isaac-HiveBoard-Franka-LeverValve-v0</code></td><td>Franka</td><td>Ball valve</td></tr><tr><td><code>Isaac-HiveBoard-Franka-CircuitBreaker-v0</code></td><td>Franka</td><td>Circuit breaker</td></tr><tr><td><code>Isaac-HiveBoard-Franka-Lamp-v0</code></td><td>Franka</td><td>Threaded lamp</td></tr><tr><td><code>Isaac-HiveBoard-Anymal-BallValve-v0</code></td><td>ANYmal with DynaArm</td><td>Ball valve</td></tr></tbody></table><p>The repository also registers camera, play, robot-only, and gripper-only configurations for debugging. Use <code>scripts/list_envs.py</code> for the complete current list. Legacy aliases remain registered for backwards compatibility; new experiments should use the <code>Isaac-HiveBoard-*</code> identifiers.</p><h2 id="run-an-environment" tabindex="-1">Run an environment <a class="header-anchor" href="#run-an-environment" aria-label="Permalink to &quot;Run an environment&quot;">​</a></h2><p>Run the Spot ball-valve task interactively:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/play.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Isaac-HiveBoard-Spot-BallValve-v0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --orbit</span></span></code></pre></div><p>Run the Franka circuit-breaker task with pose diagnostics:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/play.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Isaac-HiveBoard-Franka-CircuitBreaker-v0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --pose-debug</span></span></code></pre></div><p>For a bounded headless run on the first CUDA device:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/play.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Isaac-HiveBoard-Spot-BallValve-v0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuda:0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-steps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span></span></code></pre></div><p>Common options supported by <code>scripts/play.py</code> include <code>--num_envs</code>, <code>--device</code>, <code>--headless</code>, <code>--video</code>, <code>--fast</code>, <code>--pose-debug</code>, and <code>--max-steps</code>.</p><h2 id="record-an-example-video" tabindex="-1">Record an example video <a class="header-anchor" href="#record-an-example-video" aria-label="Permalink to &quot;Record an example video&quot;">​</a></h2><p>Record one headless episode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/play.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Isaac-HiveBoard-Spot-BallValve-v0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --video</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable_cameras</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuda:0</span></span></code></pre></div><p>To run the repository&#39;s predefined validation set, use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/record_all_examples.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuda:0</span></span></code></pre></div><p>Videos are written under <code>videos/</code> by default. The batch script records the Spot and Franka examples defined in <a href="https://github.com/EESC-LabRoM/isaaclab-hiveboard/blob/master/scripts/record_all_examples.sh" target="_blank" rel="noreferrer"><code>record_all_examples.sh</code></a>.</p><h2 id="collect-demonstrations" tabindex="-1">Collect demonstrations <a class="header-anchor" href="#collect-demonstrations" aria-label="Permalink to &quot;Collect demonstrations&quot;">​</a></h2><p>The current collector records successful fixed-base Spot ball-valve demonstrations with relative end-effector control and exports HDF5 datasets:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/collect_demos.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuda:0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --num_demos</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dataset_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spot_ball_valve_10</span></span></code></pre></div><p>Datasets are stored in <code>logs/recorded_datasets/</code> unless <code>--dataset_dir</code> is supplied. The collector also supports <code>--num_envs</code>, <code>--video</code>, <code>--keep_failed_demos</code>, and an optional reachable reset-state cache through <code>--reset_state_cache_path</code>.</p><h2 id="repository-structure" tabindex="-1">Repository structure <a class="header-anchor" href="#repository-structure" aria-label="Permalink to &quot;Repository structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>isaaclab-hiveboard/</span></span>
<span class="line"><span>├── dependencies/</span></span>
<span class="line"><span>│   ├── HiveBoard/          # Benchmark meshes and articulated assets</span></span>
<span class="line"><span>│   ├── curobo/             # CuRobo submodule</span></span>
<span class="line"><span>│   └── duatic_dynaarm/     # DynaArm description</span></span>
<span class="line"><span>├── scripts/</span></span>
<span class="line"><span>│   ├── list_envs.py</span></span>
<span class="line"><span>│   ├── play.py</span></span>
<span class="line"><span>│   ├── collect_demos.py</span></span>
<span class="line"><span>│   └── record_all_examples.sh</span></span>
<span class="line"><span>└── source/isaaclab_hiveboard/</span></span>
<span class="line"><span>    └── isaaclab_hiveboard/</span></span>
<span class="line"><span>        ├── assets/</span></span>
<span class="line"><span>        ├── mdp/</span></span>
<span class="line"><span>        ├── tasks/</span></span>
<span class="line"><span>        └── utils/</span></span></code></pre></div><h2 id="reporting-simulation-results" tabindex="-1">Reporting simulation results <a class="header-anchor" href="#reporting-simulation-results" aria-label="Permalink to &quot;Reporting simulation results&quot;">​</a></h2><p>Simulation results should identify:</p><ul><li>the full <code>isaaclab-hiveboard</code> commit;</li><li>the HiveBoard submodule commit;</li><li>Isaac Sim and Isaac Lab versions;</li><li>the task ID, robot, and end-effector;</li><li>the number of parallel environments and evaluation seeds;</li><li>any changes to task configuration, observations, actions, reset distributions, or success conditions; and</li><li>whether results were produced with a scripted controller, collected demonstrations, or a learned policy.</li></ul><p>Do not combine simulation and physical-board results into one aggregate score. Contact, friction, printed-part variation, press-fit release, and component damage are not necessarily represented by the simulation.</p>`,46)])])}const F=a(n,[["render",l]]);export{k as __pageData,F as default};
